{"implementation": "def solve(case):
    payload = case["payload"]
    segments = payload["segments"]
    budget = payload["budget"]

    # Start with minimum allocations
    allocation = {seg["name"]: seg["minimum"] for seg in segments}
    remaining = budget - sum(seg["minimum"] for seg in segments)

    if remaining < 0:
        return {"allocations": allocation, "total_importance": 0, "feasible": False}

    # Greedy: allocate remaining budget to highest-importance segments first
    sorted_segs = sorted(segments, key=lambda s: -s["importance"])

    for seg in sorted_segs:
        if remaining <= 0:
            break
        name = seg["name"]
        extra = min(remaining, seg["capacity"] - allocation[name])
        allocation[name] += extra
        remaining -= extra

    total_importance = sum(
        allocation[seg["name"]] * seg["importance"] for seg in segments
    )

    return {
        "allocations": allocation,
        "total_importance": total_importance,
        "feasible": True
    }"}
